                        if (rs.getString("ktppraktisi").equals("")) TeksArea.append("!! SKIP: NIK Dokter Kosong\n");
                        if (!rs.getString("id_clinicalimpression").equals("")) TeksArea.append("!! SKIP: Sudah Terkirim\n");
